import type { AttributedSystem, NativeResult, SystemRow, StatsResult, StatsInput, LiveStatsEvent } from "./beszel-types";
import { callWidgetIntegration, defineWidgetServer, getWidgetServerContext, subscribeWidgetIntegration } from "@homarr/widget-sdk/server";
const declaredConnections = new Set(["beszel", "secondary"]);
const getConnection = (input: {connection?:string} | undefined) => {
  const connection = input?.connection ?? "beszel";
  if (!declaredConnections.has(connection)) throw new Error("Unknown Beszel connection");
  return connection;
};
export default defineWidgetServer({
  systems: async (_input, context) => {
    const {bindingNames} = await getWidgetServerContext(context);
    const names = [...declaredConnections].filter((name) => bindingNames.includes(name));
    if (!names.length) throw new Error("Bind a Beszel integration to this widget first");
    const results = await Promise.allSettled(names.map((connection) => callWidgetIntegration<NativeResult<SystemRow[]>>(context, {connection, capability:"beszel.systems"})));
    const data: AttributedSystem[] = [];
    const sources = results.map((result, index) => {
      const connection = names[index]!;
      if (result.status === "rejected") return {connection,ok:false,error:result.reason instanceof Error ? result.reason.message : String(result.reason)};
      data.push(...result.value.data.map((system) => ({...system,connection,rowKey:`${connection}:${system.id}`})));
      return {connection,ok:true,timestamp:result.value.timestamp};
    });
    return {data,sources};
  },
  stats: (input: StatsInput, context) => callWidgetIntegration<NativeResult<StatsResult>>(context, {connection:getConnection(input),capability:"beszel.stats",input}),
  live: (input: StatsInput, context) => subscribeWidgetIntegration<LiveStatsEvent>(context, {connection:getConnection(input),capability:"beszel.live",input}),
});

