// Public result fields used from the Homarr Beszel capability adapter.
export interface SystemRow {
  id:string; name:string; status:"up"|"down"|"paused"|"pending";
  cpu:number; memory:number; disk:number; gpu:number; netBytes:number; uptime:number;
  hostname:string; cpuModel:string; cores:number; osName:string; agentVersion:string;
}
export interface AttributedSystem extends SystemRow {connection:string;rowKey:string}
export interface NativeResult<T> {data:T;timestamp?:string}
export interface SystemStats {cpu:number;mu:number;mb:number;du:number;dio?:[number,number];dr?:number;dw?:number;b?:[number,number];ns?:number;nr?:number}
export interface ContainerStats {n:string;c:number;m:number;b?:[number,number];ns?:number;nr?:number}
export interface StatsRecord<T> {id:string;created:string;stats:T}
export type SystemRecord = StatsRecord<SystemStats>;
export type ContainerRecord = StatsRecord<ContainerStats[]>;
export interface StatsResult {systemStats:SystemRecord[];containerStats:ContainerRecord[]}
export type LiveStatsEvent = {type:"system_stats";record:SystemRecord}|{type:"container_stats";record:ContainerRecord};
export interface StatsInput {connection?:string;systemId:string;timePeriod?:string;includeDocker?:boolean}

export interface SystemsResult {data:AttributedSystem[];sources:{connection:string;ok:boolean;error?:string;timestamp?:string}[]}

