import type { AttributedSystem, SystemStats, ContainerStats, LiveStatsEvent, SystemsResult, NativeResult, StatsResult } from "./beszel-types";
import type { DataTableColumn, DataTableSortStatus } from "@homarr/widget-sdk/ui";
type Layout = {columnOrder:string;columnWidths:string};
type Selection = {connection:string;id:string;name:string};
type ChartData = Array<{time:string} & Record<string,string|number>>;
import { useCallback, useMemo } from "react";
import { Alert, Badge, Button, Group, Loader, ScrollArea, SegmentedControl, SimpleGrid, Stack, Text, TextInput } from "@mantine/core";
import { LineChart } from "@mantine/charts";
import { useWidgetHost, useWidgetQuery, useWidgetServices, useWidgetState, useWidgetSubscription, useLocalWidgetState } from "@homarr/widget-sdk";
import { HomarrDataTable, usePersistedTableLayout } from "@homarr/widget-sdk/ui";

const columnAccessors = ["name", "connection", "hostname", "cpu", "memory", "disk", "gpu", "netBytes", "uptime", "cpuModel", "cores", "osName", "agentVersion"];
const colors = ["teal.6", "blue.6", "grape.6", "orange.6", "pink.6", "cyan.6"];
const mib = 1024 ** 2;
const gib = 1024 ** 3;
const rate = (bytes: number | undefined, legacy: number | undefined) => bytes ?? (legacy ?? 0) * mib;
const order = <T extends {created:string}>(records: readonly T[]) => [...records].sort((left, right) => Date.parse(left.created) - Date.parse(right.created));

function Chart({ title, data, names, unit, locale }: {title:string;data:ChartData;names:string[];unit:string;locale:string}) {
  const formatter = (value:number) => {
    if (unit === "%") return new Intl.NumberFormat(locale, { maximumFractionDigits: 1 }).format(value) + "%";
    return new Intl.NumberFormat(locale, { notation: "compact", maximumFractionDigits: 1 }).format(value) + " " + unit;
  };
  return <Stack gap={4} style={{ minWidth: 0 }}>
    <Text size="sm" fw={600}>{title}</Text>
    {data.length === 0 ? <Text c="dimmed" size="xs">Waiting for samples</Text> :
      <LineChart h={180} data={data} dataKey="time" series={names.map((name, index) => ({ name, color: colors[index % colors.length] }))} curveType="linear" valueFormatter={formatter} withDots={false} />}
  </Stack>;
}

export default function Systems() {
  const host = useWidgetHost();
  const services = useWidgetServices();
  const systems = useWidgetQuery<SystemsResult>("systems", {}, { refetchInterval: 10000 });
  const [selected, setSelected] = useWidgetState<Selection | null>("system", null);
  const [period, setPeriod] = useWidgetState("period", "1h");
  const [search, setSearch] = useWidgetState("search", "");
  const [sort, setSort] = useWidgetState<DataTableSortStatus<AttributedSystem>>("sort", { columnAccessor: "name", direction: "asc" });
  const advanced = host.displayMode === "advanced";
  const live = useWidgetSubscription<LiveStatsEvent>("live", { connection: selected?.connection ?? "beszel", systemId: selected?.id ?? "" }, { enabled: advanced && selected !== null && period === "live", maximumEvents: 120 });
  const stats = useWidgetQuery<NativeResult<StatsResult>>("stats", { connection: selected?.connection ?? "beszel", systemId: selected?.id ?? "", timePeriod: period === "live" ? "1h" : period, includeDocker: true }, { enabled: advanced && selected !== null && period !== "live", refetchInterval: 5000 });
  const records = systems.data?.data ?? [];
  const visible = records.filter((system) => `${system.name} ${system.connection} ${system.hostname}`.toLocaleLowerCase().includes(search.toLocaleLowerCase())).toSorted((a, b) => {
    const direction = sort.direction === "asc" ? 1 : -1;
    const left = a[sort.columnAccessor as keyof AttributedSystem];
    const right = b[sort.columnAccessor as keyof AttributedSystem];
    if (typeof left === "number" && typeof right === "number") return (left - right) * direction;
    return String(left ?? "").localeCompare(String(right ?? "")) * direction;
  });
  const inspect = useCallback((system: AttributedSystem) => {
    setSelected({connection: system.connection, id: system.id, name: system.name});
    if (!advanced) services.openAdvanced();
  }, [advanced, services, setSelected]);
  const [layout, setLayout] = useLocalWidgetState({
    key: host.isPreview ? undefined : `custom-widget:beszel-layout:${host.itemId}:${host.userId ?? "guest"}`,
    version: 1, defaultValue: {columnOrder: "", columnWidths: ""},
    validate: (value): value is Layout => Boolean(value && typeof value === "object" && "columnOrder" in value && "columnWidths" in value && typeof value.columnOrder === "string" && typeof value.columnWidths === "string"),
  });
  const persistLayout = useCallback((patch: Partial<Layout>) => setLayout((current) => ({...current, ...patch})), [setLayout]);
  const columns = useMemo<DataTableColumn<AttributedSystem>[]>(() => [
    {accessor:"name", title:"System", width:180, sortable:true, render: (system: AttributedSystem) => <Group gap={4} wrap="nowrap"><Badge size="xs" color={system.status === "up" ? "teal" : "gray"}>{system.status}</Badge><Button variant="subtle" size="compact-xs" onClick={(event) => {event.stopPropagation(); inspect(system);}}>{system.name}</Button></Group>},
    {accessor:"connection", title:"Source", width:100, sortable:true, hidden:!advanced},
    {accessor:"hostname", title:"Hostname", width:140, sortable:true, hidden:!advanced},
    ...(["cpu","memory","disk","gpu"] as const).map((key) => ({accessor:key, title:key.toUpperCase(), width:100, sortable:true, hidden:!advanced && (key === "gpu" || (key === "disk" && host.visibleWidth < 420)), render:(system: AttributedSystem) => <Text size="xs">{system[key].toFixed(1)}%</Text>})),
    {accessor:"netBytes", title:"Network", width:110, sortable:true, hidden:!advanced, render:(system: AttributedSystem) => <Text size="xs">{(system.netBytes / mib).toFixed(2)} MiB/s</Text>},
    {accessor:"uptime", title:"Uptime", width:100, sortable:true, hidden:!advanced, render:(system: AttributedSystem) => <Text size="xs">{Math.floor(system.uptime / 3600)} h</Text>},
    {accessor:"cpuModel", title:"CPU model", width:180, hidden:!advanced},
    {accessor:"cores", title:"Cores", width:70, sortable:true, hidden:!advanced},
    {accessor:"osName", title:"Operating system", width:140, sortable:true, hidden:!advanced},
    {accessor:"agentVersion", title:"Agent", width:90, hidden:!advanced},
  ], [advanced, host.visibleWidth, inspect]);
  const {effectiveColumns, storeKey} = usePersistedTableLayout({
    columns, columnAccessors, columnOrder:layout.columnOrder, columnWidths:layout.columnWidths,
    itemId:host.itemId ?? host.previewId, storeKeyPrefix:`custom-beszel-${host.userId ?? "guest"}`, onLayoutChange:persistLayout,
  });
  const panels = useMemo(() => {
    const systemRecords = order(period === "live" ? live.events.filter((event) => event.type === "system_stats").map((event) => event.record) : stats.data?.data?.systemStats ?? []);
    const containerRecords = order(period === "live" ? live.events.filter((event) => event.type === "container_stats").map((event) => event.record) : stats.data?.data?.containerStats ?? []);
    const formatTime = (created:string) => new Date(created).toLocaleTimeString(host.locale, { hour: "2-digit", minute: "2-digit", second: "2-digit" });
    const mapped = (fn:(stats:SystemStats)=>Record<string,number>) => systemRecords.map((record) => ({ time: formatTime(record.created), ...fn(record.stats) }));
    const containerNames = [...new Set(containerRecords.flatMap((record) => record.stats.map((container) => container.n)))];
    const containers = (fn:(stats:ContainerStats)=>number) => containerRecords.map((record) => ({ time: formatTime(record.created), ...Object.fromEntries(record.stats.map((container) => [container.n, fn(container)])) }));
    return [
      { title: "CPU", data: mapped((s) => ({ CPU: s.cpu })), names: ["CPU"], unit: "%" },
      { title: "Memory", data: mapped((s) => ({ Used: s.mu * gib, Cache: s.mb * gib })), names: ["Used", "Cache"], unit: "B" },
      { title: "Disk", data: mapped((s) => ({ Used: s.du * gib })), names: ["Used"], unit: "B" },
      { title: "Disk I/O", data: mapped((s) => ({ Read: rate(s.dio?.[0], s.dr), Write: rate(s.dio?.[1], s.dw) })), names: ["Read", "Write"], unit: "B/s" },
      { title: "Network", data: mapped((s) => ({ Sent: rate(s.b?.[0], s.ns), Received: rate(s.b?.[1], s.nr) })), names: ["Sent", "Received"], unit: "B/s" },
      { title: "Container CPU", data: containers((c) => c.c), names: containerNames, unit: "%" },
      { title: "Container memory", data: containers((c) => c.m * mib), names: containerNames, unit: "B" },
      { title: "Container network", data: containers((c) => rate(c.b?.[0], c.ns) + rate(c.b?.[1], c.nr)), names: containerNames, unit: "B/s" },
    ];
  }, [host.locale, live.events, period, stats.data]);
  return <ScrollArea h="100%"><Stack gap="sm" p="sm">
    <Group justify="space-between"><Text fw={600}>Beszel systems</Text>{systems.isFetching && <Loader size="xs" />}</Group>
    {systems.error && <Alert color="red">{systems.error.message}<Button variant="subtle" onClick={() => systems.refetch()}>Retry</Button></Alert>}
    {advanced && <TextInput aria-label="Filter systems" placeholder="Filter systems and sources" value={search} onChange={(event) => setSearch(event.currentTarget.value)} />}
    {(systems.data?.sources ?? []).filter((source) => !source.ok).map((source) => <Alert key={source.connection} color="yellow" title={source.connection}>{source.error}</Alert>)}
    <HomarrDataTable isEditMode={host.isEditMode} cellPadding="4px 8px" records={visible} columns={effectiveColumns}
      height={advanced ? 320 : Math.max(100, host.height - 64)} idAccessor="rowKey" storeColumnsKey={storeKey}
      sortStatus={sort} onSortStatusChange={setSort} noRecordsText="No systems match this view."
      onRowClick={({record}) => inspect(record)} />
    {!systems.isPending && visible.length === 0 && <Text size="sm" c="dimmed">No systems match this view.</Text>}
    {!selected && advanced && <Text size="sm" c="dimmed">Select a system to inspect its history.</Text>}
    {selected && advanced && <Stack gap="sm">
      <Text fw={600}>{selected.name} · {selected.connection}</Text>
      <SegmentedControl value={period} onChange={setPeriod} data={["live", "1h", "12h", "24h", "1w", "30d"]} size="xs" />
      {live.error && period === "live" && <Alert color="yellow">{live.error.message}<Group><Button size="compact-xs" onClick={live.reconnect}>Reconnect</Button><Button size="compact-xs" onClick={() => setPeriod("1h")}>Use history</Button></Group></Alert>}
      {stats.error && period !== "live" && <Alert color="red">{stats.error.message}</Alert>}
      <SimpleGrid cols={host.visibleWidth > 700 ? 2 : 1}>{panels.map((panel) => <Chart key={panel.title} {...panel} locale={host.locale} />)}</SimpleGrid>
    </Stack>}
  </Stack></ScrollArea>;
}
